using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup()
    {
        _tracker = new InventoryTracker();
    }

    // ──────────────────────────────────────────────
    //  GetStockLevel
    // ──────────────────────────────────────────────

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN-001"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void GetStockLevel_NullOrEmptySku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _tracker.GetStockLevel(sku!));
    }

    // ──────────────────────────────────────────────
    //  AddStock
    // ──────────────────────────────────────────────

    [TestMethod]
    public void AddStock_NewSku_SetsLevel()
    {
        _tracker.AddStock("SKU-A", 10);
        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_AccumulatesQuantity()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-A", 5);
        Assert.AreEqual(15, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddStock_NonPositiveQuantity_Throws(int quantity)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-A", quantity));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void AddStock_NullOrEmptySku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _tracker.AddStock(sku!, 5));
    }

    // ──────────────────────────────────────────────
    //  RemoveStock
    // ──────────────────────────────────────────────

    [TestMethod]
    public void RemoveStock_SufficientStock_ReducesLevel()
    {
        _tracker.AddStock("SKU-A", 20);
        _tracker.RemoveStock("SKU-A", 7);
        Assert.AreEqual(13, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_ExactAmount_LeavesZero()
    {
        _tracker.AddStock("SKU-A", 5);
        _tracker.RemoveStock("SKU-A", 5);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_InsufficientStock_Throws()
    {
        _tracker.AddStock("SKU-A", 3);
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-A", 10));
        StringAssert.Contains(ex.Message, "Insufficient stock");
    }

    [TestMethod]
    public void RemoveStock_UnknownSku_Throws()
    {
        Assert.ThrowsExactly<InvalidOperationException>(
            () => _tracker.RemoveStock("GHOST", 1));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-5)]
    public void RemoveStock_NonPositiveQuantity_Throws(int quantity)
    {
        _tracker.AddStock("SKU-A", 10);
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _tracker.RemoveStock("SKU-A", quantity));
    }

    // ──────────────────────────────────────────────
    //  Reorder Threshold & NeedsReorder
    // ──────────────────────────────────────────────

    [TestMethod]
    public void NeedsReorder_NoThresholdSet_ReturnsFalse()
    {
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", 3);
        _tracker.SetReorderThreshold("SKU-A", 5);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", 5);
        _tracker.SetReorderThreshold("SKU-A", 5);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.SetReorderThreshold("SKU-A", 5);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void SetReorderThreshold_NegativeThreshold_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _tracker.SetReorderThreshold("SKU-A", -1));
    }

    [TestMethod]
    public void SetReorderThreshold_ZeroThreshold_Allowed()
    {
        _tracker.SetReorderThreshold("SKU-A", 0);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A")); // stock 0 <= threshold 0
    }

    // ──────────────────────────────────────────────
    //  GetReorderAlerts
    // ──────────────────────────────────────────────

    [TestMethod]
    public void GetReorderAlerts_NoThresholds_ReturnsEmpty()
    {
        Assert.AreEqual(0, _tracker.GetReorderAlerts().Count);
    }

    [TestMethod]
    public void GetReorderAlerts_MultipleSkus_ReturnsOnlyThoseBelowThreshold()
    {
        _tracker.AddStock("ALPHA", 2);
        _tracker.SetReorderThreshold("ALPHA", 5);

        _tracker.AddStock("BETA", 100);
        _tracker.SetReorderThreshold("BETA", 5);

        _tracker.AddStock("GAMMA", 1);
        _tracker.SetReorderThreshold("GAMMA", 10);

        var alerts = _tracker.GetReorderAlerts();
        CollectionAssert.AreEqual(
            new[] { "ALPHA", "GAMMA" },
            alerts.ToList());
    }

    // ──────────────────────────────────────────────
    //  TransferStock
    // ──────────────────────────────────────────────

    [TestMethod]
    public void TransferStock_MovesQuantityBetweenTrackers()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-A", 20);

        _tracker.TransferStock("SKU-A", 8, destination);

        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(8, destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferStock_InsufficientStock_Throws_AndDestinationUnchanged()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-A", 3);

        Assert.ThrowsExactly<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-A", 10, destination));

        Assert.AreEqual(3, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(0, destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferStock_NullDestination_Throws()
    {
        _tracker.AddStock("SKU-A", 10);
        Assert.ThrowsExactly<ArgumentNullException>(
            () => _tracker.TransferStock("SKU-A", 5, null!));
    }

    [TestMethod]
    public void TransferStock_DestinationAccumulatesExistingStock()
    {
        var destination = new InventoryTracker();
        destination.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-A", 20);

        _tracker.TransferStock("SKU-A", 5, destination);

        Assert.AreEqual(15, destination.GetStockLevel("SKU-A"));
    }

    // ──────────────────────────────────────────────
    //  AssignWarehouse
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, "WH-1")]
    [DataRow("", "WH-1")]
    [DataRow("SKU-A", null)]
    [DataRow("SKU-A", "")]
    public void AssignWarehouse_NullOrEmptyArgs_Throws(string? sku, string? wh)
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _tracker.AssignWarehouse(sku!, wh!));
    }

    [TestMethod]
    public void AssignWarehouse_ValidArgs_DoesNotThrow()
    {
        _tracker.AssignWarehouse("SKU-A", "WH-EAST");
        // no exception = success
    }

    // ──────────────────────────────────────────────
    //  Integration / end-to-end scenario
    // ──────────────────────────────────────────────

    [TestMethod]
    public void Scenario_FullLifecycle()
    {
        _tracker.AddStock("WIDGET", 50);
        _tracker.SetReorderThreshold("WIDGET", 10);

        Assert.IsFalse(_tracker.NeedsReorder("WIDGET"));

        _tracker.RemoveStock("WIDGET", 42);
        Assert.IsTrue(_tracker.NeedsReorder("WIDGET"));
        CollectionAssert.Contains(_tracker.GetReorderAlerts().ToList(), "WIDGET");

        _tracker.AddStock("WIDGET", 30);
        Assert.IsFalse(_tracker.NeedsReorder("WIDGET"));
        Assert.AreEqual(0, _tracker.GetReorderAlerts().Count);
    }
}
